parameters.value:
={{ (() => {
    const isPage = $('Set Page Number').isExecuted;
    const isChangeVoice = $('Set Change-Voice Page Number').isExecuted;
    const isSample = $('Set Sample Voice Number').isExecuted;
    const isNormalKnit = !isPage && !isChangeVoice && !isSample;
    const isChangeVoiceKnit = isChangeVoice && $('Set Change-Voice Page Number').item.json.isKnit;
    const isKnitRender = isNormalKnit || isChangeVoiceKnit;
    const docPrefix = isSample ? '' : ($('Set Document Folder').item.json.docFolder + '/');
    const left = isNormalKnit ? $('Page Knitting Configuration').item.json['⬅️ Left Page Number'] : null;
    const right = isNormalKnit ? $('Page Knitting Configuration').item.json['Right Page Number ➡️'] : null;
    const p = isNormalKnit
      ? `${left}-${right}_knit`
      : (isPage
          ? $('Set Page Number').item.json.pageNumber
          : (isChangeVoice
              ? $('Set Change-Voice Page Number').item.json.fileBasename
              : 'sample_' + $('Set Sample Voice Number').item.json.voiceId
            )
        );
    const img = `temp/${docPrefix}${p}_image.png`;
    const name = isSample ? $('Set Sample Voice Number').item.json.friendlyName : null;

    const sampleImageCmds = isSample ? [
      'REFW=1920',
      'REFH=1080',
      'FONTSIZE=$((REFH / 12))',
      `NAME='${name}'`,
      'NAMELEN=${#NAME}',
      'CELLW=$(( (NAMELEN * FONTSIZE * 6 / 10) + FONTSIZE ))',
      'CELLH=$(( FONTSIZE * 2 ))',
      'COLS=$(( (REFW + CELLW - 1) / CELLW ))',
      'ROWS=$(( (REFH + CELLH - 1) / CELLH ))',
      'GRIDW=$((COLS * CELLW))',
      'OFFSETX=$(( (REFW - GRIDW) / 2 ))',
      'FILTERS=""',
      `for ((r=0; r<ROWS; r++)); do for ((c=0; c<COLS; c++)); do CELLX=$((OFFSETX + c*CELLW)); CELLY=$((r*CELLH)); FILTERS="\${FILTERS}drawtext=text='\${NAME}':fontcolor=black:fontsize=\${FONTSIZE}:x=\${CELLX}+(\${CELLW}-text_w)/2:y=\${CELLY}+(\${CELLH}-text_h)/2,"; done; done`,
      'FILTERS="${FILTERS%,}"',
      `ffmpeg -y -f lavfi -i color=white:s=\${REFW}x\${REFH} -vf "$FILTERS" -frames:v 1 ${img}`
    ] : [];

    const ffmpegCmd = isKnitRender
      ? `ffmpeg -y -loop 1 -t "$DUR" -i ${img} -i temp/${docPrefix}${p}_audio.wav -vf "scale=trunc(iw/2)*2:trunc(ih/2)*2" -c:v libx264 -tune stillimage -c:a aac -b:a 192k -pix_fmt yuv420p temp/${docPrefix}${p}_clip.mp4`
      : `ffmpeg -y -loop 1 -t "$DUR" -i ${img} -i temp/${docPrefix}${p}_audio.wav -filter_complex "[0:v]split[bg_src][fg_src];[bg_src]scale=iw*2:trunc(ih/2)*2,boxblur=20:3[bg];[fg_src]scale=trunc(iw/2)*2:trunc(ih/2)*2[fg];[bg][fg]overlay=(main_w-overlay_w)/2:0[v]" -map "[v]" -map 1:a -c:v libx264 -tune stillimage -c:a aac -b:a 192k -pix_fmt yuv420p temp/${docPrefix}${p}_clip.mp4`;

    return [
      'set -e',
      `export PATH=${$('Populate Variables').item.json.ffmpegPath}:$PATH`,
      ...sampleImageCmds,
      `DUR=$(ffprobe -v quiet -show_entries format=duration -of csv=p=0 temp/${docPrefix}${p}_audio.wav)`,
      `sed -i '' 's/"audioDuration":null/"audioDuration":'"$DUR"'/' temp/${docPrefix}${p}_timestamps.json`,
      ffmpegCmd,
      `(xattr -d com.apple.quarantine temp/${docPrefix}${p}_clip.mp4 2>/dev/null || true)`
    ].join(' && ');
  })() }}

