parameters.value:
={{ (() => {
    const basename = $('Determine Output Basename').item.json.outputBasename;
    const clipGlob = $('Determine Output Basename').item.json.tempClipGlob;
    const chaptersFile = $('Determine Output Basename').item.json.chaptersFile;
    const simple = $('Determine Output Basename').item.json.useSimpleConcat;
    const docPrefix = simple ? '' : ($('Set Document Folder').item.json.docFolder + '/');
    const tempDir = $('Populate Variables').item.json.tempDirRelative;
    const outputDir = $('Populate Variables').item.json.outputDirRelative;

    const sortedVoiceIds = $('Aggregate All Timestamps').item.json.pages
      .map(x => x.data)
      .filter(d => d.voiceId)
      .sort((a, b) => (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0)))
      .map(d => d.voiceId);

    const concatListCheck = `[ -s ${tempDir}/${docPrefix}${basename}_concat_list.txt ] || { echo "ERROR: concat list ${tempDir}/${docPrefix}${basename}_concat_list.txt is empty, no clips matched" >&2; exit 1; }`;

    const simpleCmds = [
      `mkdir -p ${outputDir}`,
      `: > ${tempDir}/${docPrefix}${basename}_concat_list.txt`,
      ...sortedVoiceIds.map(id => `echo "file '$PWD/${tempDir}/sample_${id}_clip.mp4'" >> ${tempDir}/${docPrefix}${basename}_concat_list.txt`),
      concatListCheck,
      `ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -c copy ${outputDir}/${docPrefix}${basename}.mp4`,
      `(xattr -d com.apple.quarantine "$PWD/${outputDir}/${docPrefix}${basename}.mp4" 2>/dev/null || true)`
    ];

    const complexCmds = [
      `mkdir -p ${outputDir}/${docPrefix}`,
      `find ${tempDir}/${docPrefix} -maxdepth 1 -name "${clipGlob}" | sort -V | while read f; do b=$(basename "$f" _clip.mp4); case "$b" in *_knit) echo "file '$PWD/$f'";; *) ls "${tempDir}/${docPrefix}${b}-"*"_knit_clip.mp4" 2>/dev/null | grep -q . || ls "${tempDir}/${docPrefix}"*"-${b}_knit_clip.mp4" 2>/dev/null | grep -q . || echo "file '$PWD/$f'";; esac; done > ${tempDir}/${docPrefix}${basename}_concat_list.txt`,
      concatListCheck,
      'MAX_W=0',
      `for f in ${tempDir}/${docPrefix}*_knit_clip.mp4; do [ -f "$f" ] || break; W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$f" | head -1); if [ "$W" -gt "$MAX_W" ]; then MAX_W=$W; fi; done`,
      `SINGLE=$(find ${tempDir}/${docPrefix} -maxdepth 1 -name "${clipGlob}" ! -name "*_knit_clip.mp4" | sort -V | head -1)`,
      'if [ -n "$SINGLE" ]; then CLIP_W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$SINGLE" | head -1); PAGE_W=$((CLIP_W/2)); if [ "$PAGE_W" -gt "$MAX_W" ]; then MAX_W=$PAGE_W; fi; else CLIP_W=$MAX_W; fi',
      'TARGET_W=$MAX_W',
      `if [ "$CLIP_W" -eq "$TARGET_W" ]; then ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -c copy ${outputDir}/${docPrefix}${basename}.mp4; elif [ "$CLIP_W" -gt "$TARGET_W" ]; then X=$(( (CLIP_W - TARGET_W) / 2 )) && ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -vf "crop=\${TARGET_W}:ih:\${X}:0" -c:v libx264 -preset ultrafast -c:a copy -pix_fmt yuv420p ${outputDir}/${docPrefix}${basename}.mp4; else OX=$(( (TARGET_W - CLIP_W) / 2 )) && ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -vf "split[bg][fg];[bg]scale=\${TARGET_W}:ih,boxblur=20:3[bg_b];[fg][bg_b]overlay=\${OX}:0" -c:v libx264 -preset ultrafast -c:a copy -pix_fmt yuv420p ${outputDir}/${docPrefix}${basename}.mp4; fi`,
      `(xattr -d com.apple.quarantine "$PWD/${outputDir}/${docPrefix}${basename}.mp4" 2>/dev/null || true)`
    ];

    return ['set -e', `export PATH=${$('Populate Variables').item.json.ffmpegPath}:$PATH`, ...(simple ? simpleCmds : complexCmds)].join(' && ');
  })() }}

