assignments.value:
={{ (() => {
      function formatSrtTimestamp(seconds) {
        seconds = Math.max(0, seconds);
        const hours = String(Math.floor(seconds / 3600)).padStart(2, '0');
        const minutes = String(Math.floor((seconds % 3600) / 60)).padStart(2, '0');
        const secs = String(Math.floor(seconds % 60)).padStart(2, '0');
        const ms = String(Math.round((seconds % 1) * 1000)).padStart(3, '0');
        return hours + ':' + minutes + ':' + secs + ',' + ms;
      }

      function stripNonAlphanumeric(word) {
        return word.toLowerCase().replace(/[^a-z0-9]/g, '');
      }

      function buildNormalizedWordList(wordMap) {
        const normList = [];
        for (let origIdx = 0; origIdx < wordMap.length; origIdx++) {
          const normalizedTokens = wordMap[origIdx].normalized.split(/\s+/).filter(w => /\w/.test(w));
          if (normalizedTokens.length > 0) {
            for (const token of normalizedTokens) normList.push({ word: token.toLowerCase(), origIdx });
          } else {
            normList.push({ word: '', origIdx });
          }
        }
        return normList;
      }

      function alignTimestampsToOriginalWords(timestamps, normList) {
        let cursor = 0;
        return timestamps.map(t => {
          const cleanedWord = stripNonAlphanumeric(t.word);
          for (let j = cursor; j < Math.min(cursor + 60, normList.length); j++) {
            if (stripNonAlphanumeric(normList[j].word) === cleanedWord) {
              cursor = j + 1;
              return normList[j].origIdx;
            }
          }
          return normList[Math.min(cursor, normList.length - 1)].origIdx;
        });
      }

      function buildSubtitleChunksForPage(page, timeOffset, startIdx) {
        const timestamps = page.timestamps.filter(t => /\w/.test(t.word));
        const pageDuration = page.audioDuration ?? page.timestamps[page.timestamps.length - 1].end_time;
        const originalWords = page.wordMap.map(w => w.original);

        const normList = buildNormalizedWordList(page.wordMap);
        const alignedOrigIdx = alignTimestampsToOriginalWords(timestamps, normList);

        const numChunks = Math.max(1, Math.ceil(pageDuration / 4));
        const wordsPerChunk = Math.ceil(timestamps.length / numChunks);

        const chunks = [];
        let i = 0, chunkIdx = startIdx;
        while (i < timestamps.length) {
          const isLastChunk = i + wordsPerChunk >= timestamps.length;
          const chunkStart = timestamps[i].start_time;
          const chunkEnd = isLastChunk ? pageDuration : timestamps[i + wordsPerChunk].start_time;
          const startOrigIdx = alignedOrigIdx[i];
          const endOrigIdx = isLastChunk ? originalWords.length - 1 : alignedOrigIdx[Math.min(i + wordsPerChunk - 1, alignedOrigIdx.length - 1)];
          chunks.push({
            idx: chunkIdx,
            start: formatSrtTimestamp(chunkStart + timeOffset),
            end: formatSrtTimestamp(chunkEnd + timeOffset),
            text: originalWords.slice(startOrigIdx, endOrigIdx + 1).join(' ')
          });
          chunkIdx++;
          i += wordsPerChunk;
        }
        return { chunks, pageDuration };
      }

      const allPages = $json.pages.map(p => p.data).sort((a, b) => (a.voiceId && b.voiceId) ? (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0)) : (a.pageIndex - b.pageIndex));
      const knitCovered = new Set(allPages.filter(p => p.knitPages).flatMap(p => p.knitPages));
      const pages = allPages.filter(p => p.knitPages || !knitCovered.has(p.pageIndex));
      const allChunks = [];
      let timeOffset = 0, chunkIdx = 1;
      for (const page of pages) {
        const { chunks, pageDuration } = buildSubtitleChunksForPage(page, timeOffset, chunkIdx);
        allChunks.push(...chunks);
        chunkIdx += chunks.length;
        timeOffset += pageDuration;
      }
      return allChunks;
    })() }}

={{ (() => {
      const allPages = $json.pages.map(p => p.data).sort((a, b) => (a.voiceId && b.voiceId) ? (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0)) : (a.pageIndex - b.pageIndex));
      const knitCovered = new Set(allPages.filter(p => p.knitPages).flatMap(p => p.knitPages.map(Number)));
      const pages = allPages.filter(p => p.knitPages || !knitCovered.has(Number(p.pageIndex)));

      let meta = ';FFMETADATA1\n', offset = 0;

      for (const page of pages) {
        const dur = page.audioDuration ?? page.timestamps[page.timestamps.length - 1].end_time;
        const title = page.voiceLabel ? page.voiceLabel : (page.knitPages ? `Pages ${page.knitPages[0]} & ${page.knitPages[1]}` : `Page ${page.pageIndex}`);
        meta += `\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=${Math.round(offset * 1000)}\nEND=${Math.round((offset + dur) * 1000)}\ntitle=${title}\n`;
        offset += dur;
      }

      return meta;
    })() }}

={{ (() => {
    const chunks = $json.subtitleChunks;
    let srt = '';
    for (const c of chunks) {
      const words = c.text.split(' ');
      const mid = Math.ceil(words.length / 2);
      const line1 = words.slice(0, mid).join(' ');
      const line2 = words.slice(mid).join(' ');
      const text = line2 ? line1 + '\n' + line2 : line1;
      srt += c.idx + '\n' + c.start + ' --> ' + c.end + '\n' + text + '\n\n';
    }
    return srt.trim();
  })() }}

