={{ [
  {
    fieldLabel: "Which page do you want to convert?",
    fieldName: "pageSelection",
    fieldType: "dropdown",
    fieldOptions: {
      values: (() => {
        const allPages = $json.pages.map(p => p.data).sort((a, b) => a.pageIndex - b.pageIndex);
        const knitCovered = new Set(allPages.filter(p => p.knitPages).flatMap(p => p.knitPages.map(Number)));
        const pages = allPages.filter(p => p.knitPages || !knitCovered.has(Number(p.pageIndex)));
        return pages.map(p => {
          const label = p.knitPages ? ('Pages ' + p.knitPages[0] + ' & ' + p.knitPages[1]) : ('Page ' + p.pageIndex);
          return { option: label };
        });
      })()
    },
    requiredField: true
  },
  {
    fieldLabel: "In what voice?",
    fieldName: "voice",
    fieldType: "dropdown",
    fieldOptions: {
      values: $('Fetch Available Voices').item.json.voices.map(v => {
        const langMap = { a: 'English (US)', b: 'English (UK)', e: 'Spanish', f: 'French', h: 'Hindi', i: 'Italian', j: 'Japanese', p: 'Portuguese (BR)', z: 'Chinese' };
        const genderMap = { f: 'Female', m: 'Male' };
        const lang = langMap[v.id[0]] || v.id[0];
        const gender = genderMap[v.id[1]] || v.id[1];
        const friendlyName = v.id.split('_')[1][0].toUpperCase() + v.id.split('_')[1].slice(1);
        return { option: v.id + " - " + friendlyName + " " + gender + " " + lang };
      })
    },
    requiredField: true
  },
  {
    fieldLabel: "Apply the voice to:",
    fieldName: "target",
    fieldType: "radio",
    fieldOptions: {
      values: [
        { option: "The entire page (starts converting right away)" },
        { option: "Selected text (continue to the next page to choose the exact words)" }
      ]
    },
    requiredField: true
  }
] }}

assignments.value:
={{
(() => {
  const parsed = JSON.parse($json.text);
  const wordMap = parsed.wordMap;
  const existingSpans = parsed.voiceSpans || [];
  const voice = $('Set Change-Voice Page Number').item.json.voice;
  const target = $('Set Change-Voice Page Number').item.json.target;
  const defaultVoice = $('Set Default Voice').isExecuted
    ? $('Set Default Voice').item.json.voice
    : ((Object.keys($('Read Default Voice').item.binary || {}).length > 0)
        ? $('Extract Default Voice').item.json.text.trim()
        : $('Populate Variables').item.json.defaultFallbackVoice);

  let newStart, newEnd;
  if (target === 'entire') {
    newStart = 0;
    newEnd = wordMap.length - 1;
  } else {
    const words = $('Set Change-Voice Page Number').item.json.textToChange
      .replace(/\|/g, ',')
      .replace(/ > /g, ', ')
      .replace(/[–—]/g, ' ')
      .trim().split(/\s+/).filter(w => w);
    if (words.length === 0) return JSON.stringify({ found: false });

    let matchStart = -1;
    for (let i = 0; i <= wordMap.length - words.length; i++) {
      let ok = true;
      for (let k = 0; k < words.length; k++) {
        if (wordMap[i + k].original.toLowerCase() !== words[k].toLowerCase()) { ok = false; break; }
      }
      if (ok) { matchStart = i; break; }
    }
    if (matchStart === -1) return JSON.stringify({ found: false });
    newStart = matchStart;
    newEnd = matchStart + words.length - 1;
  }

  const survivingSpans = existingSpans.filter(s => s.end < newStart || s.start > newEnd);
  const allSpans = [...survivingSpans, { start: newStart, end: newEnd, voice }].sort((a, b) => a.start - b.start);

  const parts = [];
  let cursor = 0;
  for (const span of allSpans) {
    if (span.start > cursor) {
      parts.push(wordMap.slice(cursor, span.start).map(w => w.normalized).join(' '));
    }
    parts.push(`[voice:${span.voice}] ${wordMap.slice(span.start, span.end + 1).map(w => w.normalized).join(' ')} [voice:${defaultVoice}]`);
    cursor = span.end + 1;
  }
  if (cursor < wordMap.length) {
    parts.push(wordMap.slice(cursor).map(w => w.normalized).join(' '));
  }
  const wrapped = parts.filter(Boolean).join(' ');

  return JSON.stringify({ found: true, text: wrapped, wordMap: wordMap, voiceSpans: allSpans });
})()
}}

