parameters.jsonOutput:
={{ [
  {
    fieldLabel: "What text should be read in that voice?",
    fieldName: "textToChange",
    fieldType: "textarea",
    defaultValue: (() => {
      const label = $('Change Voice Configuration').item.json.pageSelection;
      const allPages = $('Aggregate All Timestamps').item.json.pages.map(p => p.data);
      const match = allPages.find(p => {
        const l = p.knitPages ? ('Pages ' + p.knitPages[0] + ' & ' + p.knitPages[1]) : ('Page ' + p.pageIndex);
        return l === label;
      });
      return match ? match.wordMap.map(w => w.original).join(' ') : '';
    })(),
    requiredField: true
  }
] }}
